        return None

@staticmethod
def get_random_username():
    username = make_request('GET', '/random_username/')
    if username:
        st.success(f'Random Username: {username}')

@staticmethod
def find_nearest_users(email, x):
    if not email or '@' not in email:
        st.error('Please enter a valid email address')
    else:
        users = make_request('GET', '/nearest_users/', params={'email':
            email, 'x': x})
        if users:
            m = folium.Map(location=[users[0]['latitude'], users[0][
                'longitude']], zoom_start=10)
            for user in users:
                st.write(
                    f"Name: {user['first_name']} {user['last_name']}, Email: {user['email']}"
                    )
                folium.Marker([user['latitude'], user['longitude']], popup=
                    f"{user['first_name']} {user['last_name']}", tooltip=
                    user['email']).add_to(m)
            folium_static(m)

